CREATE TABLE framing_settings (business_id TEXT PRIMARY KEY NOT NULL, default_markup_percent INTEGER NOT NULL DEFAULT 0 CHECK(default_markup_percent>=0), default_labour_cents INTEGER NOT NULL DEFAULT 0 CHECK(default_labour_cents>=0), default_moulding_waste_percent INTEGER NOT NULL DEFAULT 0 CHECK(default_moulding_waste_percent>=0), default_material_waste_percent INTEGER NOT NULL DEFAULT 0 CHECK(default_material_waste_percent>=0), updated_at TEXT NOT NULL);
CREATE TABLE frame_mouldings (id TEXT PRIMARY KEY NOT NULL,business_id TEXT NOT NULL,code TEXT,name TEXT NOT NULL,description TEXT,face_width_mm INTEGER,cost_per_meter_cents INTEGER NOT NULL CHECK(cost_per_meter_cents>=0),sale_price_per_meter_cents INTEGER CHECK(sale_price_per_meter_cents IS NULL OR sale_price_per_meter_cents>=0),waste_percent INTEGER CHECK(waste_percent IS NULL OR waste_percent>=0),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sync_origin TEXT NOT NULL DEFAULT 'local',local_revision INTEGER NOT NULL DEFAULT 0,cloud_updated_at TEXT,UNIQUE(business_id,id));
CREATE TABLE frame_materials (id TEXT PRIMARY KEY NOT NULL,business_id TEXT NOT NULL,name TEXT NOT NULL,material_type TEXT NOT NULL CHECK(material_type IN('glass','backing','passepartout','print','other')),pricing_unit TEXT NOT NULL CHECK(pricing_unit IN('square_meter','linear_meter','unit')),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),sale_price_cents INTEGER CHECK(sale_price_cents IS NULL OR sale_price_cents>=0),waste_percent INTEGER CHECK(waste_percent IS NULL OR waste_percent>=0),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sync_origin TEXT NOT NULL DEFAULT 'local',local_revision INTEGER NOT NULL DEFAULT 0,cloud_updated_at TEXT,UNIQUE(business_id,id));
CREATE TABLE frame_quotes (id TEXT PRIMARY KEY NOT NULL,business_id TEXT NOT NULL,branch_id TEXT NOT NULL,customer_id TEXT,width_mm INTEGER NOT NULL CHECK(width_mm>0),height_mm INTEGER NOT NULL CHECK(height_mm>0),measurement_mode TEXT NOT NULL CHECK(measurement_mode='opening'),status TEXT NOT NULL CHECK(status IN('draft','quoted','accepted','rejected','expired')),notes TEXT,subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sync_origin TEXT NOT NULL DEFAULT 'local',local_revision INTEGER NOT NULL DEFAULT 0,cloud_updated_at TEXT,UNIQUE(business_id,id),FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id) ON DELETE RESTRICT);
CREATE TABLE frame_quote_items (id TEXT PRIMARY KEY NOT NULL,business_id TEXT NOT NULL,quote_id TEXT NOT NULL,item_type TEXT NOT NULL CHECK(item_type IN('moulding','material','labour')),source_id TEXT,name_snapshot TEXT NOT NULL,quantity_numerator INTEGER NOT NULL CHECK(quantity_numerator>0),quantity_denominator INTEGER NOT NULL CHECK(quantity_denominator>0),unit TEXT NOT NULL CHECK(unit IN('square_meter','linear_meter','unit','labour')),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),total_cents INTEGER NOT NULL CHECK(total_cents>=0),metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(business_id,id),FOREIGN KEY(business_id,quote_id) REFERENCES frame_quotes(business_id,id) ON DELETE RESTRICT);
CREATE TABLE frame_jobs (id TEXT PRIMARY KEY NOT NULL,business_id TEXT NOT NULL,branch_id TEXT NOT NULL,quote_id TEXT NOT NULL,customer_id TEXT,status TEXT NOT NULL CHECK(status IN('pending','in_progress','ready','delivered','cancelled')),promised_at TEXT,notes TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sync_origin TEXT NOT NULL DEFAULT 'local',local_revision INTEGER NOT NULL DEFAULT 0,cloud_updated_at TEXT,UNIQUE(business_id,id),UNIQUE(business_id,quote_id),FOREIGN KEY(business_id,quote_id) REFERENCES frame_quotes(business_id,id) ON DELETE RESTRICT,FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id) ON DELETE RESTRICT);
CREATE INDEX frame_quotes_list_idx ON frame_quotes(business_id,branch_id,status,updated_at DESC); CREATE INDEX frame_jobs_list_idx ON frame_jobs(business_id,branch_id,status,updated_at DESC); CREATE INDEX frame_quote_items_quote_idx ON frame_quote_items(business_id,quote_id,created_at);
